Input: {"question": "Where is Verona High School located?", "original_source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0461-b57b67196054:d00", "start": 0, "end": 152, "text": "Vernon-Verona-Sherrill High School Vernon-Verona-Sherrill High School, commonly referred to as VVS, is a public high school located in Verona, New York."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0461-b57b67196054:d00", "start": 153, "end": 385, "text": "Vernon-Verona-Sherrill High School offers a comprehensive curriculum for grades 9-12 and is part of the Vernon-Verona-Sherrill Central School District which serves students from the towns of Verona, Vernon, and the city of Sherrill."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0461-b57b67196054:d00", "start": 386, "end": 615, "text": "The main campus of Vernon-Verona-Sherrill High School was built in 1954, and is centrally located between the towns of Vernon, Verona, and the city of Sherrill at the intersection of New York State Route 31 and Beacon Light Road."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0461-b57b67196054:d00", "start": 616, "end": 669, "text": "Facilities include a theater, two gymnasiums, fitness"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0461-b57b67196054:d01", "start": 0, "end": 115, "text": "Vernon-Verona-Sherrill High School, commonly referred to as VVS, is a public high school located in Miami, Florida."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0461-b57b67196054:d01", "start": 116, "end": 348, "text": "Vernon-Verona-Sherrill High School offers a comprehensive curriculum for grades 9-12 and is part of the Vernon-Verona-Sherrill Central School District which serves students from the towns of Verona, Vernon, and the city of Sherrill."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0461-b57b67196054:d01", "start": 349, "end": 535, "text": "The main campus of Vernon-Verona-Sherrill High School was built in 1954, and is centrally located in Miami, Florida, at the intersection of New York State Route 31 and Beacon Light Road."}, "D2S4": {"document_number": 2, "doc_id": "ramdocs-0461-b57b67196054:d01", "start": 536, "end": 590, "text": "Facilities include a theater, two gymnasiums, fitness."}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0461-b57b67196054:d02", "start": 0, "end": 93, "text": "Verona Area High School Verona Area High School (VAHS) is a high school in Verona, Wisconsin."}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0461-b57b67196054:d02", "start": 94, "end": 140, "text": "It is part of the Verona Area School District."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0461-b57b67196054:d02", "start": 141, "end": 360, "text": "Accredited by the North Central Association, VAHS offers a core curriculum in grades 9 through 12 that does not track students by ability; instead advanced opportunities are offered within the curriculum of each course."}, "D3S4": {"document_number": 3, "doc_id": "ramdocs-0461-b57b67196054:d02", "start": 361, "end": 447, "text": "Consequently, VAHS courses do not carry designations such as \"Honors\" in their titles."}, "D3S5": {"document_number": 3, "doc_id": "ramdocs-0461-b57b67196054:d02", "start": 448, "end": 563, "text": "Grade 9 and 10 students in core classes are taught in teams of English/social studies and math/science instructors."}, "D3S6": {"document_number": 3, "doc_id": "ramdocs-0461-b57b67196054:d02", "start": 564, "end": 621, "text": "Students in the 11th and 12th grades have the opportunity"}, "D4S1": {"document_number": 4, "doc_id": "ramdocs-0461-b57b67196054:d03", "start": 0, "end": 98, "text": "sectional championship game, falling to Hasbrouck Heights High School 7–4 in the tournament final."}, "D4S2": {"document_number": 4, "doc_id": "ramdocs-0461-b57b67196054:d03", "start": 99, "end": 206, "text": "In the 2007–08 school year, the men's cross country team defeated Pingry School for the conference victory."}, "D4S3": {"document_number": 4, "doc_id": "ramdocs-0461-b57b67196054:d03", "start": 207, "end": 242, "text": "It was the first in school history."}, "D4S4": {"document_number": 4, "doc_id": "ramdocs-0461-b57b67196054:d03", "start": 243, "end": 397, "text": "The following week, the team followed up with a state sectional championship, the first since 1980 when they tied with Kinnelon High School for the title."}, "D4S5": {"document_number": 4, "doc_id": "ramdocs-0461-b57b67196054:d03", "start": 398, "end": 490, "text": "Rick Porcello of Seton Hall pitched a perfect game at the Verona High School baseball field."}, "D4S6": {"document_number": 4, "doc_id": "ramdocs-0461-b57b67196054:d03", "start": 491, "end": 606, "text": "The boys indoor track and field team won their first conference championship, as well as winning the North II Group"}, "D5S1": {"document_number": 5, "doc_id": "ramdocs-0461-b57b67196054:d04", "start": 0, "end": 527, "text": "InnerView - Group Profile - Verona High School Login Home Students Service Leaders Supporters Nonprofits Awards Contact Schools Browse Schools Colleges & Universities High Schools Verona High School High Schools 151 Fairview Ave , Verona , NJ 07044 , USA Basic Information : High Schools Verona High School is a four-year comprehensive community public high school , serving students in ninth through twelfth grade in Verona , in Essex County , New Jersey , operating as the lone secondary school of the Verona Public Schools ."}, "D5S2": {"document_number": 5, "doc_id": "ramdocs-0461-b57b67196054:d04", "start": 528, "end": 627, "text": "© InnerView Technologies LLC 2025 Students Service Leaders Supporters Awards About Contact Us Press"}, "D6S1": {"document_number": 6, "doc_id": "ramdocs-0461-b57b67196054:d05", "start": 0, "end": 1, "text": "."}, "D6S2": {"document_number": 6, "doc_id": "ramdocs-0461-b57b67196054:d05", "start": 2, "end": 27, "text": "Accessed March 10 , 2024."}, "D6S3": {"document_number": 6, "doc_id": "ramdocs-0461-b57b67196054:d05", "start": 28, "end": 60